SERIES = {"novotestamento": NT, "antigotestamento": AT}


def prompts() -> None:
    md = RAIZ / "prompts-higgsfield.md"
    texto = md.read_text(encoding="utf-8")
    if "[CENA]" in texto:
        raise SystemExit("As séries bíblicas já estão no prompts-higgsfield.md.")
    linhas = ["", "## Séries bíblicas (40 passagens do Novo Testamento e 40 do Antigo)", "",
              "Trocar `[CENA]` pela coluna Figura:", "", "> " + BASE, "",
              "Ao conferir: os itens da coluna Conferir aparecem, na quantidade certa; sem texto nem letras; borda sem símbolos.", ""]
    for titulo, inicio, lista in (("Novo Testamento", 401, NT), ("Antigo Testamento", 501, AT)):
        linhas += [f"**{titulo}**", "", "| # | id | Passagem | Figura | Conferir | Objetos |", "|---|---|---|---|---|---|"]
        linhas += [f"| {inicio + n} | {i} | {nome} | {cena} | {conf} | - |" for n, (i, nome, cena, conf, *_resto) in enumerate(lista)]
        linhas.append("")
    md.write_text(texto.rstrip("\n") + "\n" + "\n".join(linhas), encoding="utf-8")
    print(f"{len(NT) + len(AT)} passagens acrescentadas ao prompts-higgsfield.md")


def index() -> None:
    from biblia_perguntas import FRASES_EXTRAS, PERGUNTAS, PERGUNTAS_EXTRAS, RECORTES, RECORTES_EXTRAS
    from biblia_rascunho import FRASES_RASCUNHO, PERGUNTAS_RASCUNHO
    itens = []
    for serie, lista in SERIES.items():
        for i, nome, _cena, _conf, ref, resumo, why in lista:
            grupo, texto, certa, erradas, onde, frase, versiculo = PERGUNTAS[i]
            itens.append({"id": i, "name": nome, "feast": ref, "bio": resumo, "why": why, "serie": serie, "grupo": grupo,
                          "recs": [list(r) for r in [RECORTES[i], *RECORTES_EXTRAS.get(i, [])]], "qs": [{"t": t, "c": c, "e": e, "ref": r} for t, c, e, r in [(texto, certa, erradas, onde), *PERGUNTAS_EXTRAS.get(i, [])]]
                          + [{"t": t, "c": c, "e": e, "ref": r, "rascunho": True} for t, c, e, r in PERGUNTAS_RASCUNHO.get(i, [])],
                          "frases": [{"t": t, "ref": r} for t, r in [(frase, versiculo), *FRASES_EXTRAS.get(i, [])]]
                          + [{"t": t, "ref": r, "rascunho": True} for t, r in FRASES_RASCUNHO.get(i, [])]})
    linha = "  const PASSAGENS = " + json.dumps(itens, ensure_ascii=False) + ";"
    arq = RAIZ / "index.html"
    with open(arq, encoding="utf-8", newline="") as f:  # newline="" preserva o fim de linha que o arquivo já usa
        texto = f.read()
    fim = "\r\n" if "\r\n" in texto else "\n"
    partes = texto.split(fim)
    onde = [n for n, l in enumerate(partes) if l.startswith("  const PASSAGENS = ")]
    if len(onde) != 1:
        raise SystemExit("O index.html deveria ter exatamente uma linha `const PASSAGENS = `.")
    partes[onde[0]] = linha
    with open(arq, "w", encoding="utf-8", newline="") as f:
        f.write(fim.join(partes))
    print(f"{len(itens)} passagens gravadas no index.html")


if __name__ == "__main__":
    prompts() if sys.argv[1:] == ["prompts"] else index()
